// apps/web/src/features/viewport/VisualViewportVars.tsx (concept)
const vv = window.visualViewport;
root.style.setProperty('--vvh', `${vv.height}px`);
root.style.setProperty('--vvw', `${vv.width}px`);
root.style.setProperty('--vv-offset-top', `${vv.offsetTop}px`);

.chrome-nav {
  top: max(env(safe-area-inset-top, 0px), 1rem);
  height: calc(var(--vvh, 100vh) - env(safe-area-inset-top, 0px));
}

